package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a new owner whose city already contains {@link #CAPACITY} or more owners, so the request is
 * answered with a 409 Conflict rather than exceeding the per-city capacity. City is compared
 * case-insensitively with surrounding whitespace trimmed, consistent with the other create-time checks.
 * Runs after {@link CheckHouseholdUnique} and before {@link BuildOwner}.
 */
public class CheckCityCapacity {

    /** Maximum number of owners permitted per city. */
    static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsNormalized(city, existing.getCity())) {
                count++;
            }
        }
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city, CAPACITY);
        }
    }

    private static boolean equalsNormalized(String a, String b) {
        if (a == null || b == null) {
            return a == null && b == null;
        }
        return a.trim().equalsIgnoreCase(b.trim());
    }
}
